static const UINT8 *GuLookupWideGlyph(CHAR16 ch) {
  UINTN lo = 0U, hi = GU_WIDE_GLYPH_COUNT;
  UINT16 target = (UINT16)ch;
  while (lo < hi) {
    UINTN mid = lo + (hi - lo) / 2U;
    UINT16 cur = GuFont16x16Wide[mid].cp;
    if (cur == target) return GuFont16x16Wide[mid].rows;
    if (cur < target) lo = mid + 1U;
    else hi = mid;
  }
  return NULL;
}

