static const CHAR16 *GuTr(UINT32 lang, GU_STR_ID id) {
  if (id >= GU_STR_COUNT) return L"";
  UINT32 idx = (lang < GU_LANG_COUNT) ? lang : GU_LANG_EN;
  const CHAR16 *s = GuUiStrings[id][idx];
  return s ? s : GuUiStrings[id][GU_LANG_EN];
}
